<?php

namespace Parle;

use JetBrains\PhpStorm\Immutable;

/**
 * <div id="class.parle-rlexer" class="reference"> <h1 class="title">The Parle\RLexer class</h1>  <div class="partintro"><p class="verinfo">(PECL parle &gt;= 0.5.1)</p>  <div class="section" id="parle-rlexer.intro">   <h2 class="title">简介</h2>   <p class="para">    Multistate lexer class. Lexemes can be defined on the fly. If the particular lexer instance is meant to be used with <span class="classname"><a href="https://php.net/manual/zh/class.parle-rparser.php" class="classname">Parle\RParser</a></span>, the token IDs need to be taken from there. Otherwise, arbitrary token IDs can be supplied. Note, that <span class="classname"><a href="https://php.net/manual/zh/class.parle-parser.php" class="classname">Parle\Parser</a></span> is not compatible with this lexer.   </p>  </div>  <div class="section" id="parle-rlexer.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">Parle\RLexer</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.constants.icase"><var class="varname">ICASE</var></a></var><span class="initializer"> = 1</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.constants.dot-not-lf"><var class="varname">DOT_NOT_LF</var></a></var><span class="initializer"> = 2</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.constants.dot-not-cr-lf"><var class="varname">DOT_NOT_CRLF</var></a></var><span class="initializer"> = 4</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.constants.skip-ws"><var class="varname">SKIP_WS</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.constants.match-zero-len"><var class="varname">MATCH_ZERO_LEN</var></a></var><span class="initializer"> = 16</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.props.bol">\$<var class="varname">bol</var></a></var><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.props.flags">\$<var class="varname">flags</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.props.state">\$<var class="varname">state</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.props.marker">\$<var class="varname">marker</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.parle-rlexer.php#parle-rlexer.props.cursor">\$<var class="varname">cursor</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.advance.php" class="methodname" style="color:#CC7832">advance</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.build.php" class="methodname" style="color:#CC7832">build</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.callout.php" class="methodname" style="color:#CC7832">callout</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.consume.php" class="methodname" style="color:#CC7832">consume</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.dump.php" class="methodname" style="color:#CC7832">dump</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.gettoken.php" class="methodname" style="color:#CC7832">getToken</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parle-token.php" class="type Parle\Token" style="color:#EAB766">Parle\Token</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.insertmacro.php" class="methodname" style="color:#CC7832">insertMacro</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.push.php" class="methodname" style="color:#CC7832">push</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.push.php" class="methodname" style="color:#CC7832">push</a></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$state</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$newState</span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.push.php" class="methodname" style="color:#CC7832">push</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$state</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$newState</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.pushstate.php" class="methodname" style="color:#CC7832">pushState</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$state</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-rlexer.reset.php" class="methodname" style="color:#CC7832">reset</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$pos</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section" id="parle-rlexer.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="parle-rlexer.constants.icase"><strong><span>{@link Parle\RLexer::ICASE}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-rlexer.constants.dot-not-lf"><strong><span>{@link Parle\RLexer::DOT_NOT_LF}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-rlexer.constants.dot-not-cr-lf"><strong><span>Parle\RLexer::DOT_NOT_CRLF</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-rlexer.constants.skip-ws"><strong><span>{@link Parle\RLexer::SKIP_WS}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-rlexer.constants.match-zero-len"><strong><span>{@link Parle\RLexer::MATCH_ZERO_LEN}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section" id="parle-rlexer.props">   <h2 class="title">属性</h2>   <dl>         <dt id="parle-rlexer.props.bol"><var class="varname">bol</var></dt>     <dd>      <p class="para">Start of input flag.</p>     </dd>             <dt id="parle-rlexer.props.flags"><var class="varname">flags</var></dt>     <dd>      <p class="para">Lexer flags.</p>     </dd>             <dt id="parle-rlexer.props.state"><var class="varname">state</var></dt>     <dd>      <p class="para">Current lexer state, readonly.</p>     </dd>             <dt id="parle-rlexer.props.marker"><var class="varname">marker</var></dt>     <dd>      <p class="para">Position of the latest token match, readonly.</p>     </dd>             <dt id="parle-rlexer.props.cursor"><var class="varname">cursor</var></dt>     <dd>      <p class="para">Current input offset, readonly.</p>     </dd>       </dl>  </div> </div>  <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Parle\RLexer::advance} — Process next lexer rule</li><li>{@link Parle\RLexer::build} — Finalize the lexer rule set</li><li>{@link Parle\RLexer::callout} — Define token callback</li><li>{@link Parle\RLexer::consume} — Pass the data for processing</li><li>{@link Parle\RLexer::dump} — Dump the state machine</li><li>{@link Parle\RLexer::getToken} — Retrieve the current token</li><li>{@link Parle\RLexer::insertMacro} — Insert regex macro</li><li>{@link Parle\RLexer::push} — Add a lexer rule</li><li>{@link Parle\RLexer::pushState} — Push a new start state</li><li>{@link Parle\RLexer::reset} — Reset lexer</li></ul></div>
 * 
 * Multistate lexer class.
 * Lexemes can be defined on the fly. If the particular lexer instance is meant to be used with Parle\RParser,
 * the token IDs need to be taken from there. Otherwise, arbitrary token IDs can be supplied.
 * Note, that Parle\Parser is not compatible with this lexer.
 *
 * @see RParser
 * @package Parle
 */
class RLexer
{
    /* Constants */
    public const ICASE = 1;
    public const DOT_NOT_LF = 2;
    public const DOT_NOT_CRLF = 4;
    public const SKIP_WS = 8;
    public const MATCH_ZERO_LEN = 16;

    /* Properties */
    /**
     * @var bool Start of input flag.
     */
    public $bol = false;

    /**
     * @var int Lexer flags.
     */
    public $flags = 0;

    /**
     * @var int Current lexer state, readonly.
     */
    #[Immutable]
    public $state = 0;

    /**
     * @var int Position of the latest token match, readonly.
     */
    #[Immutable]
    public $marker = 0;

    /**
     * @var int Current input offset, readonly.
     */
    #[Immutable]
    public $cursor = 0;

    /* Methods */

    /**
 * <div id="parle-rlexer.advance" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\RLexer::advance</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\RLexer::advance</span> — <span class="dc-title">Process next lexer rule</span></p> </div> <div class="refsect1 description" id="refsect1-parle-rlexer.advance-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::advance</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Processes the next rule and prepares the resulting token data.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-rlexer.advance-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-parle-rlexer.advance-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Processes the next rule and prepares the resulting token data.
     *
     * @link https://php.net/manual/zh/parle-rlexer.advance.php
     * @return void
     */
    public function advance(): void {}

    /**
 * <div id="parle-rlexer.build" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\RLexer::build</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\RLexer::build</span> — <span class="dc-title">Finalize the lexer rule set</span></p> </div> <div class="refsect1 description" id="refsect1-parle-rlexer.build-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::build</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Rules, previously added with <span class="methodname" style="color:#CC7832">{@link Parle\RLexer::push()}</span> are finalized. This method call has to be done after all the necessary rules was pushed. The rule set becomes read only. The lexing can begin.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-rlexer.build-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-parle-rlexer.build-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Finalize the lexer rule set
     *
     * Rules, previously added with Parle\RLexer::push() are finalized.
     * This method call has to be done after all the necessary rules was pushed.
     * The rule set becomes read only. The lexing can begin.
     *
     * @link https://php.net/manual/zh/parle-rlexer.build.php
     * @see RLexer::push()
     * @return void
     */
    public function build(): void {}

    /**
