    /**
 * <div id="parle-rlexer.push" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\RLexer::push</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\RLexer::push</span> — <span class="dc-title">Add a lexer rule</span></p> </div> <div class="refsect1 description" id="refsect1-parle-rlexer.push-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::push</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::push</strong></span>(<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$state</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>,<br>&nbsp;&nbsp;&nbsp;&nbsp;<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$newState</span></span><br>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::push</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$state</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$regex</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$newState</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Push a pattern for lexeme recognition.  </p>  <p class="para">A 'start state' and 'exit state' can be specified by using a suitable signature.   </p> </div> <div class="refsect1 parameters" id="refsect1-parle-rlexer.push-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">regex</span></dt>    <dd>     <p class="para">      Regular expression used for token matching.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">id</span></dt>    <dd>     <p class="para">      Token id. If the lexer instance is meant to be used standalone, this can be an arbitrary number. If the lexer instance is going to be passed to the parser, it has to be an id returned by <span class="methodname" style="color:#CC7832">{@link Parle\RParser::tokenid()}</span>.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">state</span></dt>    <dd>     <p class="para">      State name. If '*' is used as start state, then the rule is applied to all lexer states.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">newState</span></dt>     <dd>      <p class="para">       New state name, after the rule was applied.      </p>      <p class="para">       If '.' is specified as the exit state, then the lexer state is unchanged when that rule matches. An exit state with '&gt;' before the name means push. Use the signature without id for either continuation or to start matching, when a continuation or recursion is required.      </p>      <p class="para">       If '&lt;' is specified as exit state, it means pop. In that case, the signature containing the id can be used to identify the match. Note that even in the case an id is specified, the rule will finish first when all the previous pushes popped.      </p>     </dd>        </dl> </div> <div class="refsect1 returnvalues" id="refsect1-parle-rlexer.push-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Add a lexer rule
     *
     * Push a pattern for lexeme recognition.
     * A 'start state' and 'exit state' can be specified by using a suitable signature.
     *
     * @param string $state State name. If '*' is used as start state, then the rule is applied to all lexer states.
     * @param string $regex Regular expression used for token matching.
     * @param string $newState
     * New state name, after the rule was applied.
     * If '.' is specified as the exit state, then the lexer state is unchanged when that rule matches.
     * An exit state with '>' before the name means push. Use the signature without id for either continuation or to
     * start matching, when a continuation or recursion is required.
     * If '<' is specified as exit state, it means pop. In that case, the signature containing the id can be used to
     * identify the match. Note that even in the case an id is specified, the rule will finish first when all the
     * previous pushes popped.
     * @return void
     * @link https://php.net/manual/zh/parle-rlexer.push.php
     */
    public function push(string $state, string $regex, string $newState): void {}

    /**
 * <div id="parle-rlexer.pushstate" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\RLexer::pushState</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\RLexer::pushState</span> — <span class="dc-title">Push a new start state</span></p> </div> <div class="refsect1 description" id="refsect1-parle-rlexer.pushstate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::pushState</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$state</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">   This lexer type can have more than one state machine. This allows you to lex different tokens depending on context, thus allowing simple parsing to take place. Once a state pushed, it can be used with a suitable <span class="methodname" style="color:#CC7832">{@link Parle\RLexer::push()}</span> signature variant.   </p> </div> <div class="refsect1 parameters" id="refsect1-parle-rlexer.pushstate-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">state</span></dt>    <dd>     <p class="para">      Name of the state.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-parle-rlexer.pushstate-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">     </p> </div></div>
 * 
     * Push a new start state
     * This lexer type can have more than one state machine.
     * This allows you to lex different tokens depending on context, thus allowing simple parsing to take place.
     * Once a state pushed, it can be used with a suitable Parle\RLexer::push() signature variant.
     *
     * @see RLexer::push()
     * @link https://php.net/manual/zh/parle-rlexer.pushstate.php
     * @param string $state Name of the state.
     * @return int
     */
    public function pushState(string $state): int {}

    /**
 * <div id="parle-rlexer.reset" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\RLexer::reset</h1>  <p class="verinfo">(PECL parle &gt;= 0.7.1)</p><p class="refpurpose"><span class="refname">Parle\RLexer::reset</span> — <span class="dc-title">Reset lexer</span></p> </div> <div class="refsect1 description" id="refsect1-parle-rlexer.reset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\RLexer::reset</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$pos</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Reset lexing optionally supplying the desired offset.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-rlexer.reset-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">pos</span></dt>    <dd>     <p class="para">      Reset position.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-parle-rlexer.reset-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Reset lexer
     *
     * Reset lexing optionally supplying the desired offset.
     *
     * @param int $pos Reset position.
     */
    public function reset(int $pos): void {}
}
